import type { ComponentProps } from 'react';

import { ScrollView, SizableText, XStack, YStack } from '@onekeyhq/components';

import { PERP_DESKTOP_ORDER_INFO_SUB_TABS_HEIGHT } from '../utils/tableLayout';

function OrderInfoSubTabs<T extends string>({
  tabs,
  activeTab,
  onChange,
  variant: _variant = 'underline',
  leftInset,
}: {
  tabs: {
    key: T;
    label: string;
  }[];
  activeTab: T;
  onChange: (tab: T) => void;
  variant?: 'pill' | 'underline';
  leftInset?: ComponentProps<typeof XStack>['pl'];
}) {
  const isPillVariant = _variant === 'pill';
  const resolvedLeftInset = leftInset ?? (isPillVariant ? '$2' : '$5');

  return (
    <XStack mt={isPillVariant ? '$2' : undefined}>
      <ScrollView
        horizontal
        showsHorizontalScrollIndicator={false}
        bounces={false}
        width="100%"
        contentContainerStyle={{
          minWidth: isPillVariant ? undefined : '100%',
        }}
      >
        <XStack
          minWidth={isPillVariant ? undefined : '100%'}
          pl={resolvedLeftInset}
          pr={isPillVariant ? '$4' : '$5'}
          py={isPillVariant ? '$1.5' : '$0'}
          gap={isPillVariant ? '$2' : '$5'}
          borderBottomWidth={isPillVariant ? 0 : '$px'}
          borderBottomColor="$borderSubdued"
        >
          {tabs.map((tab) => {
            const isFocused = activeTab === tab.key;
            const pillBg = (() => {
              if (!isPillVariant) {
                return undefined;
              }
              return isFocused ? '$bgActive' : 'transparent';
            })();
            return (
              <YStack
                key={tab.key}
                h={
                  isPillVariant
                    ? undefined
                    : PERP_DESKTOP_ORDER_INFO_SUB_TABS_HEIGHT - 1
                }
                px={isPillVariant ? '$2' : '$0'}
                py={isPillVariant ? '$1' : '$0'}
                onPress={() => onChange(tab.key)}
                position="relative"
                alignItems="center"
                justifyContent="center"
                cursor="pointer"
                userSelect="none"
                borderRadius={isPillVariant ? '$4' : undefined}
                bg={pillBg}
                {...(isPillVariant && !isFocused
                  ? {
                      hoverStyle: {
                        bg: '$bgStrongHover',
                      },
                      pressStyle: {
                        bg: '$bgStrongActive',
                      },
                    }
                  : undefined)}
              >
                <SizableText
                  numberOfLines={1}
                  size={isPillVariant ? '$bodySmMedium' : '$bodySmMedium'}
                  color={isFocused ? '$text' : '$textSubdued'}
                >
                  {tab.label}
                </SizableText>
                {!isPillVariant && isFocused ? (
                  <YStack
                    position="absolute"
                    bottom={0}
                    left={0}
                    right={0}
                    h="$0.5"
                    bg="$text"
                    borderRadius={1}
                  />
                ) : null}
              </YStack>
            );
          })}
        </XStack>
      </ScrollView>
    </XStack>
  );
}

export { OrderInfoSubTabs };
